package cz.mh.rallye.rallye_backend.races;
import java.time.Instant;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import cz.mh.rallye.rallye_backend.races.domain.EventLifecycle;
class EventLifecycleTest {
 final Instant at=Instant.parse("2026-10-30T10:00:00Z");
 final EventLifecycle.Metadata empty=new EventLifecycle.Metadata(null,null,null,0,0,null,null);
 @Test void projectionHasInclusiveDeadlinesAndEndPriority(){assertEquals("PLANNED",EventLifecycle.effective("PLANNED",at.plusMillis(1),null,at));assertEquals("RUNNING",EventLifecycle.effective("PLANNED",at,null,at));assertEquals("ENDED",EventLifecycle.effective("PLANNED",at,at,at));assertEquals("ENDED",EventLifecycle.effective("RUNNING",null,at,at));assertEquals("ENDED",EventLifecycle.effective("ENDED",null,null,at));}
 @Test void pendingStartDoesNotInventStoredPeriodButAllowsManualWinner(){var v=EventLifecycle.view("PLANNED",at.minusSeconds(5),null,empty,at);assertTrue(v.transitionsPending());assertTrue(v.canStart());assertTrue(v.canEnd());assertFalse(v.canEditEndAt());assertNull(v.startedAt());assertNull(v.activePeriodId());assertEquals(0,v.periodNumber());assertEquals(at.minusSeconds(5),v.effectiveStartedAt());}
 @Test void pendingEndDisablesAllMutationCapabilities(){var v=EventLifecycle.view("PLANNED",at.minusSeconds(5),at,empty,at);assertTrue(v.transitionsPending());assertFalse(v.canStart());assertFalse(v.canEnd());assertFalse(v.canResume());assertNull(v.effectiveStartedAt());assertNull(v.currentClosureRevision());assertEquals("PENDING_TRANSITION",v.resumeBlockedReason());}
 @Test void closureAndFirstStartSurviveResumeProjection(){UUID period=UUID.randomUUID();var m=new EventLifecycle.Metadata(at.minusSeconds(100),at.minusSeconds(10),period,2,1,null,null);var v=EventLifecycle.view("RUNNING",null,null,m,at);assertTrue(v.canEnd());assertTrue(v.canEditEndAt());assertFalse(v.canStart());assertEquals(period,v.activePeriodId());assertEquals(m.startedAt(),v.startedAt());assertEquals(m.lastEndedAt(),v.lastEndedAt());assertNull(v.currentClosureRevision());}
 @Test void finalizedResultsBlockResume(){var m=new EventLifecycle.Metadata(null,at,null,0,1,1L,at);var v=EventLifecycle.view("ENDED",null,null,m,at);assertFalse(v.canResume());assertEquals("RESULTS_FINALIZED",v.resumeBlockedReason());assertEquals(1L,v.currentClosureRevision());}
 @Test void aggregatePredicateMatchesPureStateForAllRelevantCombinations(){for(String status:new String[]{"PLANNED","RUNNING","ENDED"})for(Instant start:new Instant[]{null,at.minusSeconds(1),at,at.plusSeconds(1)})for(Instant end:new Instant[]{null,at.minusSeconds(1),at,at.plusSeconds(1)}){boolean sqlActive=!status.equals("ENDED")&&(end==null||end.isAfter(at));assertEquals(!EventLifecycle.effective(status,start,end,at).equals("ENDED"),sqlActive);}}
 @Test void onlyExpectedBusinessValidationMayBeDeferredPastCommit(){var result=cz.mh.rallye.rallye_backend.races.application.LifecycleService.validate(()->{throw new cz.mh.rallye.rallye_backend.identity.application.AuthFailure(409,"RACE_EVENT_VERSION_CONFLICT");});assertEquals("RACE_EVENT_VERSION_CONFLICT",result.failure().code());assertThrows(cz.mh.rallye.rallye_backend.identity.application.AuthFailure.class,result::get);assertThrows(IllegalStateException.class,()->cz.mh.rallye.rallye_backend.races.application.LifecycleService.validate(()->{throw new IllegalStateException("Technical");}));}
 @Test void unavailableChecksCannotCommitPartialReconciliation(){assertThrows(cz.mh.rallye.rallye_backend.identity.application.AuthFailure.class,()->cz.mh.rallye.rallye_backend.races.application.LifecycleService.validate(()->{throw new cz.mh.rallye.rallye_backend.identity.application.AuthFailure(503,"RACE_EVENT_RESULTS_CHECK_UNAVAILABLE");}));}
}
